const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(140.468626, -45.432798);
  const buffer_radius_km = 100;
  const geometry = point.buffer(buffer_radius_km * 1000); // Buffer in meters

  // Define comparison periods
  const start_date_current = '2019-11-01';
  const end_date_current = '2020-02-29'; // Account for leap year
  const start_date_prior = '2018-11-01';
  const end_date_prior = '2019-02-28';

  const band_name = 'chlor_a'; // Chlorophyll-a concentration

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3/CHL');

  const col_current = collection
    .filterDate(start_date_current, end_date_current)
    .filterBounds(geometry)
    .select(band_name);

  const col_prior = collection
    .filterDate(start_date_prior, end_date_prior)
    .filterBounds(geometry)
    .select(band_name);

  // Check if collections are empty
  const size_current = await col_current.size().getInfo();
  const size_prior = await col_prior.size().getInfo();

  if (size_current === 0 || size_prior === 0) {
    console.log(`Current Period Images: ${size_current}`);
    console.log(`Prior Period Images: ${size_prior}`);
    console.log('C1: Empty Collection (No images found for one or both comparison points).');
    return;
  }

  // 3. Processing & Calculation
  // Calculate mean image for each period
  const mean_img_current = col_current.mean();
  const mean_img_prior = col_prior.mean();

  // Define scale for reduction. MODIS-Aqua L3 CHL is ~4.6km resolution. Using 5000m scale.
  const scale = 5000;

  // Reduce region for mean chlorophyll-a and pixel count
  const reducers = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats_current = await mean_img_current.reduceRegion({
    reducer: reducers,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const stats_prior = await mean_img_prior.reduceRegion({
    reducer: reducers,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const mean_chlor_current = stats_current ? stats_current[band_name] : null;
  const count_pixels_current = stats_current ? stats_current[band_name + '_count'] : 0;
  const mean_chlor_prior = stats_prior ? stats_prior[band_name] : null;
  const count_pixels_prior = stats_prior ? stats_prior[band_name + '_count'] : 0;

  // 4. Validation & Final Answer
  console.log(`Current Period (Nov 2019 - Feb 2020) Images: ${size_current}`);
  console.log(`Prior Period (Nov 2018 - Feb 2019) Images: ${size_prior}`);
  console.log(`Current Chlorophyll Mean: ${mean_chlor_current !== null ? mean_chlor_current.toFixed(4) : 'N/A'}, Valid Pixels: ${count_pixels_current}`);
  console.log(`Prior Chlorophyll Mean: ${mean_chlor_prior !== null ? mean_chlor_prior.toFixed(4) : 'N/A'}, Valid Pixels: ${count_pixels_prior}`);

  if (count_pixels_current === 0 || count_pixels_prior === 0) {
    console.log('C2: No Valid Pixels (Images exist, but after processing, 0 pixels remain).');
    return;
  }

  if (mean_chlor_current === null || isNaN(mean_chlor_current) ||
      mean_chlor_prior === null || isNaN(mean_chlor_prior)) {
    console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
    return;
  }

  if (mean_chlor_current > mean_chlor_prior) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
